from ortools.sat.python import cp_model
import math
import json

def main():
    model = cp_model.CpModel()

    A = list(range(1, 9))
    coordinates = {
        0: (0.0, 0.0),
        9: (1.0, 1.0),
        1: (0.2, 0.3),
        2: (0.5, 0.1),
        3: (0.8, 0.4),
        4: (0.6, 0.7),
        5: (0.3, 0.6),
        6: (0.1, 0.8),
        7: (0.7, 0.2),
        8: (0.4, 0.5)
    }

    v = {
        1: 10,
        2: 15,
        3: 20,
        4: 12,
        5: 18,
        6: 8,
        7: 14,
        8: 16
    }

    D_max = 2.5

    locations = [0] + A + [9]
    d = {}
    for p in locations:
        for q in locations:
            if p != q:
                x1, y1 = coordinates[p]
                x2, y2 = coordinates[q]
                distance = math.sqrt((x1 - x2)**2 + (y1 - y2)**2)
                d[(p, q)] = distance

    z = {}
    for i in A:
        z[i] = model.NewBoolVar(f"z_{i}")

    x = {}
    for p in locations:
        for q in locations:
            if p != q:
                x[(p, q)] = model.NewBoolVar(f"x_{p}_{q}")

    M = len(A) + 2
    u = {}
    for p in locations:
        u[p] = model.NewIntVar(0, M, f"u_{p}")

    start_outgoing = []
    for q in A + [9]:
        start_outgoing.append(x[(0, q)])
    model.Add(sum(start_outgoing) == 1)

    end_incoming = []
    for p in [0] + A:
        end_incoming.append(x[(p, 9)])
    model.Add(sum(end_incoming) == 1)

    for i in A:
        incoming = []
        for p in [0] + A:
            if p != i:
                incoming.append(x[(p, i)])
        model.Add(sum(incoming) == z[i])

        outgoing = []
        for q in A + [9]:
            if q != i:
                outgoing.append(x[(i, q)])
        model.Add(sum(outgoing) == z[i])

    for i in A:
        incoming = []
        outgoing = []
        for p in [0] + A:
            if p != i:
                incoming.append(x[(p, i)])
        for q in A + [9]:
            if q != i:
                outgoing.append(x[(i, q)])

    for p in locations:
        for q in locations:
            if p != q:
                model.Add(u[q] >= u[p] + 1 - M * (1 - x[(p, q)]))

    model.Add(u[0] == 0)

    total_visited = sum(z[i] for i in A)
    model.Add(u[9] == total_visited + 1)

    distance_terms = []
    for p in locations:
        for q in locations:
            if p != q:
                scaled_distance = int(round(d[(p, q)] * 1000))
                distance_terms.append(scaled_distance * x[(p, q)])

    scaled_max_distance = int(round(D_max * 1000))
    model.Add(sum(distance_terms) <= scaled_max_distance)

    objective_terms = []
    for i in A:
        objective_terms.append(v[i] * z[i])

    model.Maximize(sum(objective_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 120.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        visited_attractions = {}
        for i in A:
            visited_attractions[i] = solver.Value(z[i]) == 1

        path = [0]
        current = 0

        while current != 9:
            for q in locations:
                if q != current and solver.Value(x[(current, q)]) == 1:
                    path.append(q)
                    current = q
                    break

        total_distance = 0.0
        for i in range(len(path) - 1):
            p = path[i]
            q = path[i + 1]
            total_distance += d[(p, q)]

        total_meaningful_value = 0
        for i in A:
            if visited_attractions[i]:
                total_meaningful_value += v[i]

        visited_attractions_list = [0] * 10
        for i in range(1, 9):
            visited_attractions_list[i] = 1 if visited_attractions[i] else 0
        visited_attractions_list[0] = 1
        visited_attractions_list[9] = 1

        print(json.dumps({
            "path": path,
            "visited_attractions": visited_attractions_list,
            "total_meaningful_value": total_meaningful_value,
            "total_distance": round(total_distance, 2)
        }))

    else:
        print(json.dumps({
            "path": [],
            "visited_attractions": [],
            "total_meaningful_value": 0,
            "total_distance": 0.0
        }))

if __name__ == "__main__":
    main()
